var c = new ActionDescriptor(); c.putDouble(C2T('Rd  '), 243); c.putDouble(C2T('Grn '), 235); c.putDouble(C2T('Bl  '), 216);
var t = new ActionDescriptor(); t.putObject(C2T('Clr '), C2T('RGBC'), c);
var u = new ActionDescriptor(); u.putObject(C2T('Type'), S2T('solidColorLayer'), t);
var r = new ActionReference(); r.putClass(S2T('contentLayer'));
var m = new ActionDescriptor(); m.putReference(C2T('null'), r); m.putObject(C2T('Usng'), S2T('contentLayer'), u);
executeAction(tk('make'), m, DialogModes.NO);
setMode('multiply');

function paperGrad() { var st = [[0,0,0,0],[228,220,203,4096]], i, g = new ActionDescriptor(); g.putString(C2T('Nm  '), 'plan'); g.putEnumerated(C2T('GrdF'), C2T('GrdF'), C2T('CstS')); g.putDouble(C2T('Intr'), 4096);
  var cs = new ActionList(), ts = new ActionList();
  for (i = 0; i < 2; i++) { var c = new ActionDescriptor(), k = new ActionDescriptor(); k.putDouble(C2T('Rd  '), st[i][0]); k.putDouble(C2T('Grn '), st[i][1]); k.putDouble(C2T('Bl  '), st[i][2]);
    c.putObject(C2T('Clr '), C2T('RGBC'), k); c.putEnumerated(C2T('Type'), C2T('Clry'), C2T('UsrS')); c.putInteger(C2T('Lctn'), st[i][3]); c.putInteger(C2T('Mdpn'), 50); cs.putObject(C2T('Clrt'), c); }
  for (i = 0; i < 2; i++) { var t = new ActionDescriptor(); t.putUnitDouble(C2T('Opct'), C2T('#Prc'), 100); t.putInteger(C2T('Lctn'), i * 4096); t.putInteger(C2T('Mdpn'), 50); ts.putObject(C2T('TrnS'), t); }
  g.putList(C2T('Clrs'), cs); g.putList(C2T('Trns'), ts);
  var a = new ActionDescriptor(); a.putBoolean(S2T('dither'), false); a.putBoolean(S2T('reverse'), false); a.putObject(S2T('gradient'), S2T('gradientClassEvent'), g);
  var u = new ActionDescriptor(); u.putObject(S2T('type'), S2T('gradientMapClass'), a);
  var m = new ActionDescriptor(), r = new ActionReference(); r.putClass(S2T('adjustmentLayer')); m.putReference(C2T('null'), r); m.putObject(S2T('using'), S2T('adjustmentLayer'), u); executeAction(S2T('make'), m, DialogModes.NO); }
function dropouts(blur, thr, name) {
  var n = d.artLayers.add(); n.name = name; d.activeLayer = n;
  d.selection.selectAll(); d.selection.fill(hexc('#808080')); d.selection.deselect();
  n.applyAddNoise(400, NoiseDistribution.GAUSSIAN, true); n.applyGaussianBlur(blur); n.autoLevels();
  var t = new ActionDescriptor(); t.putInteger(C2T('Lvl '), thr); executeAction(C2T('Thrs'), t, DialogModes.NO);
  paperGrad(); d.activeLayer.merge(); d.activeLayer.blendMode = BlendMode.LIGHTEN; }
dropouts(6, 192, 'blotches'); dropouts(1.2, 205, 'specks');
d.flatten();

function rn(s) { var v = Math.sin(s * 12.9898) * 43758.5453; return v - Math.floor(v); }
function edge(x0, y0, x1, y1, seed, amp) { var pts = [], len = Math.sqrt((x1 - x0) * (x1 - x0) + (y1 - y0) * (y1 - y0)), n = Math.round(len / 5), nx = -(y1 - y0) / len, ny = (x1 - x0) / len, i;
  for (i = 0; i < n; i++) { var t = i / n, off = amp * (0.55 * Math.sin(t * 7 + seed) + 0.3 * Math.sin(t * 19 + seed * 2.3) + 0.15 * Math.sin(t * 47 + seed * 5)) + (rn(i * 3 + seed * 11) - 0.5) * amp * 0.7;
    pts.push([x0 + (x1 - x0) * t + nx * off, y0 + (y1 - y0) * t + ny * off]); } return pts; }
var pts = edge(380, 190, 1540, 190, 1, 26).concat(edge(1540, 190, 1540, 890, 2, 26), edge(1540, 890, 380, 890, 3, 26), edge(380, 890, 380, 190, 4, 26));
d.selection.select(pts, SelectionType.REPLACE, 0, true);
var c = new ActionDescriptor(); c.putDouble(C2T('Rd  '), 242); c.putDouble(C2T('Grn '), 236); c.putDouble(C2T('Bl  '), 221);
var t = new ActionDescriptor(); t.putObject(C2T('Clr '), C2T('RGBC'), c);
var u = new ActionDescriptor(); u.putObject(C2T('Type'), S2T('solidColorLayer'), t);
var r = new ActionReference(); r.putClass(S2T('contentLayer'));
var m = new ActionDescriptor(); m.putReference(C2T('null'), r); m.putObject(C2T('Usng'), S2T('contentLayer'), u);
executeAction(tk('make'), m, DialogModes.NO);
d.selection.deselect();
